{
  "category_edits": [
    {
      "category": "training_strategy",
      "rationale": "Across all four datasets, replace validation-triggered learning-rate decay with a fixed schedule: retain the initial rate for epochs 1–10, halve it at epochs 11, 31 and 51, then retain the 0.125 floor. Smaller late updates may stabilize ranking while preserving all other training and modeling choices.",
      "edits": [
        {
          "find": "    scheduler = torch.optim.lr_scheduler.ReduceLROnPlateau(\n        optimizer, mode=\"max\", factor=0.5, patience=1,\n        threshold=0.0, threshold_mode=\"abs\", min_lr=LR * 0.125\n    )",
          "replace": "    initial_lrs = [group[\"lr\"] for group in optimizer.param_groups]"
        },
        {
          "find": "    for epoch in range(1, NUM_EPOCHS + 1):\n        model.train()",
          "replace": "    for epoch in range(1, NUM_EPOCHS + 1):\n        decay_steps = 0 if epoch <= 10 else 1 + (epoch - 11) // 20\n        lr_scale = max(0.125, 0.5 ** decay_steps)\n        for group, initial_lr in zip(optimizer.param_groups, initial_lrs):\n            group[\"lr\"] = initial_lr * lr_scale\n        model.train()"
        },
        {
          "find": "            scheduler.step(hr10)\n",
          "replace": ""
        }
      ]
    }
  ],
  "change_summary": "Changed only the learning-rate schedule for all four category models. Optimizer, architecture, loss, early stopping, seeds, epoch cap and predictor remain unchanged."
